import{_ as a}from"./chunks/fleet-tracking.BorPpiUb.js";import{_ as t,o as i,c as r,a2 as n}from"./chunks/framework.CWgsre3x.js";const f=JSON.parse('{"title":"Fleet tracking and telematics","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/live-tracking.md","filePath":"integrations/live-tracking.md"}'),o={name:"integrations/live-tracking.md"};function s(l,e,c,d,p,h){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="fleet-tracking-and-telematics" tabindex="-1">Fleet tracking and telematics <a class="header-anchor" href="#fleet-tracking-and-telematics" aria-label="Permalink to &quot;Fleet tracking and telematics&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Source-reviewed draft · v0.7.9 reference. Confirm availability and permissions against the approved target release.</p></div><h2 id="illustrated-workspace" tabindex="-1">Illustrated workspace <a class="header-anchor" href="#illustrated-workspace" aria-label="Permalink to &quot;Illustrated workspace&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/fleet-tracking.png"><img src="'+a+'" alt="Fleet Tracking / Live Operations: reservation milestones and fleet assignments. The screen explicitly reports that external GPS, flight and AIS providers are fail-closed."></a></p><p><em>Select the screenshot to open it at its original size. Use your browser’s Back button to return.</em></p><p><em>Fleet Tracking / Live Operations: reservation milestones and fleet assignments. The screen explicitly reports that external GPS, flight and AIS providers are fail-closed.</em></p><p>Staging capture, TransferBook+ v0.7.11; English UI. Illustrative test data. This image does not establish production availability. Identifiers masked.</p><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Live vehicle tracking requires a configured telematics provider. The baseline distinguishes demonstration data from live positions and does not establish a working production GPS connection.</p><h2 id="operational-procedure" tabindex="-1">Operational procedure <a class="header-anchor" href="#operational-procedure" aria-label="Permalink to &quot;Operational procedure&quot;">​</a></h2><ol><li>Confirm the provider and company connection with an authorized administrator.</li><li>Check that the displayed data is identified as live rather than simulated before making dispatch decisions.</li><li>If tracking is unavailable, use verified reservation assignments and direct operational contact under your company&#39;s procedures.</li></ol><p>Never infer a real driver&#39;s location from a demonstration marker or an estimated arrival from an unverified feed. Do not publish driver location screenshots containing personal data.</p><p>See <a href="/plus/fleet-management.html">Fleet management</a> and <a href="/plus/assignments.html">Driver and vehicle assignment</a>.</p><h2 id="v0-7-26-operational-tracking" tabindex="-1">v0.7.26 operational tracking <a class="header-anchor" href="#v0-7-26-operational-tracking" aria-label="Permalink to &quot;v0.7.26 operational tracking&quot;">​</a></h2><p>The historical screenshot above is v0.7.11 and does not depict current GPS capability. The v0.7.26 source supports a local geographical canvas and authenticated chauffeur positions. Sharing requires explicit driver opt-in and on-duty authorization; freshness, accuracy and revocation matter. Dispatchers should confirm the correct hub and leg, check the last report and treat stale/missing coordinates as unavailable, not proof of movement. The independent return leg may have a different chauffeur.</p><p>Optional licensed Google map and road estimates require their own configuration and acceptance. Physical mobile GPS acceptance and automatic external flight/ferry tracking remain outstanding. See <a href="/integrations/maps-arrivals-setup.html">Maps and arrivals setup</a> and <a href="/plus/arrival-intelligence.html">Arrival intelligence</a>.</p>',16)])])}const g=t(o,[["render",s]]);export{f as __pageData,g as default};
